INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(53911, 'Numbers 8:16', 'Numbers', 8, 16, 'لاویان یوازې زما دي او هغوی مې د اسراییلو د ټولو مشرانو زامنو په ځای قبول کړي دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers8_verse_16.mp3', '', 1761754199, 1761754199),
(53912, 'Numbers 8:17', 'Numbers', 8, 17, 'کله چې ما د مصریانو مشران زامن او لومړني زېږېدلي حیوانات ووژل، دا پرېکړه مې وکړه چې په هرې اسراییلي کورنۍ کې مشران زامن او د هغوی د رمو او پادو څخه هر لومړنی زېږېدلی نر حیوان به زما وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers8_verse_17.mp3', '', 1761754199, 1761754199),
(53913, 'Numbers 8:18', 'Numbers', 8, 18, 'خو اوس ما د اسراییلو د ټولو مشرانو زامنو په ځای لاویان غوره کړي دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers8_verse_18.mp3', '', 1761754199, 1761754199),
(53914, 'Numbers 8:19', 'Numbers', 8, 19, 'د ټولو اسراییلیانو څخه مې لاویان هارون او د هغه زامنو ته د سوغاتونو په توګه ورکړي دي چې په سپېڅلې خېمه کې د قوم په خاطر کار وکړي او د هغوی دپاره کفاره ادا کړي، ترڅو کله چې اسراییلیان سپېڅلي ځای ته ورنژدې کیږي، په هغوی باندې کوم افت رانه شي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers8_verse_19.mp3', '', 1761754199, 1761754199),
(53915, 'Numbers 8:20', 'Numbers', 8, 20, 'لکه څنګه چې څښتن موسی ته حکم کړی ؤ، نو موسی، هارون او د اسراییلو ټول قوم لاویان وقف کړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers8_verse_20.mp3', '', 1761754199, 1761754199),
(53916, 'Numbers 8:21', 'Numbers', 8, 21, 'لاویانو خپل ځانونه پاک کړل او خپل کالي یې ووینځل او هارون هغوی د یو ځانګړي سوغات په توګه څښتن ته وقف کړل او د هغوی د پاکوالي دپاره یې کفاره ادا کړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers8_verse_21.mp3', '', 1761754199, 1761754199),
(53917, 'Numbers 8:22', 'Numbers', 8, 22, 'له دې وروسته لکه څنګه چې څښتن حکم کړی ؤ، لاویانو د هارون او د هغه د زامنو د مرستیالانو په توګه په سپېڅلې خېمه کې کار کاوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers8_verse_22.mp3', '', 1761754199, 1761754199),
(53918, 'Numbers 8:23', 'Numbers', 8, 23, 'څښتن موسی ته وویل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers8_verse_23.mp3', '', 1761754199, 1761754199),
(53919, 'Numbers 8:26', 'Numbers', 8, 26, 'هغوی کولای شي چې د سپېڅلې خېمې په دندو کې د نورو لاویانو سره مرسته وکړي، خو په خپله باید د کوم کار مسوولیت په غاړه ونه لري. په دې ډول لاویانو ته دندې وسپاره.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers8_verse_26.mp3', '', 1761754199, 1761754199),
(53920, 'Hosea 13:1', 'Hosea', 13, 1, 'په تېر وخت کې کله چې د افرایم قبیلې خبرې کولې، نو د اسراییلو نورې قبیلې به لړزېدلې، هغوی به افرایم ته د درناوي په سترګه کتل. خو د افرایم خلک بعل ته په عبادت کولو سره د ګناه د سزا لایق شول او د دې کار په سبب به هغوی مړه شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea13_verse_1.mp3', '', 1761754199, 1761754199),
(53921, 'Hosea 13:2', 'Hosea', 13, 2, 'هغوی د خپلو ځانونو دپاره فلزي مجسمې جوړوي او د خپلو سپینو زرو څخه د خپلو لاسونو په مهارت بتان جوړوي او په دې کار سره اوس زیاته ګناه کوي او بیا وایي: «د هغو دپاره قربانۍ وړاندې کړئ!» څوک څنګه کولای شي چې دغه بتان چې د خوسیانو په شکل جوړ شوي دي، ښکل کړي!', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea13_verse_2.mp3', '', 1761754199, 1761754199),
(53922, 'Hosea 13:3', 'Hosea', 13, 3, 'نو دا خلک به لکه د سهار د لړو او دوپ په شان ورک شي او لکه د پرخې په شان چې سهار وختي له منځه ځي. هغوی به د هغو بوسو په شان وي چې باد یې له درمند څخه وړي او د هغه لوګي په شان چې د سوري نه وځي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea13_verse_3.mp3', '', 1761754199, 1761754199),
(53923, 'Hosea 13:4', 'Hosea', 13, 4, 'څښتن وایي: «زه ستاسو هماغه څښتن خدای یم چې د مصر نه یې راوویستلئ. پرته زما نه بل خدای مه منئ. زه ستاسو یوازېنی ژغورونکی یم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea13_verse_4.mp3', '', 1761754199, 1761754199),
(53924, 'Hosea 13:5', 'Hosea', 13, 5, 'هغه زه وم چې په وچه دښته کې مې په تاسو باندې پام کاوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea13_verse_5.mp3', '', 1761754199, 1761754199),
(53925, 'Hosea 13:6', 'Hosea', 13, 6, 'خو کله چې ما تاسو ته خواړه درکړل او تاسو ماړه شوئ، نو بیا مغروره شوئ او زه مو هېر کړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea13_verse_6.mp3', '', 1761754199, 1761754199),
(53926, 'Hosea 13:7', 'Hosea', 13, 7, 'نو زه به په تاسو باندې لکه د زمري په شان حمله وکړم. د پړانګ په شان به ستاسو په لاره کې په کمین کې کښېنم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea13_verse_7.mp3', '', 1761754199, 1761754199),
(53927, 'Hosea 13:8', 'Hosea', 13, 8, 'زه به تاسو باندې د هغې اېږې په شان چې بچي یې غلا شوي وي، حمله وکړم او ستاسو سینه به څیرې کړم. تاسو به لکه د زمري په شان وخورم او د ځنګلي حیوان په شان به مو ټوټې ټوټې کړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea13_verse_8.mp3', '', 1761754199, 1761754199),
(53928, 'Hosea 13:9', 'Hosea', 13, 9, 'ای د اسراییلو خلکو! زه به تاسو تباه کړم، نو بیا څوک کولای شي ستاسو سره مرسته وکړي؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea13_verse_9.mp3', '', 1761754199, 1761754199),
(53929, 'Hosea 13:10', 'Hosea', 13, 10, 'اوس ستاسو پاچا چېرته دی چې په خپلو ټولو ښارونو کې تاسو وژغوري؟ او ستاسو حاکمان چېرته دي چې تاسو به غوښتل او ویل به مو چې مونږ ته پاچا او مامورین راکړه؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea13_verse_10.mp3', '', 1761754199, 1761754199),
(53930, 'Hosea 13:11', 'Hosea', 13, 11, 'ما په خپل قهر کې تاسو ته پاچاهان درکړل او د خپل غضب په وخت کې مې بېرته درڅخه واخیستل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea13_verse_11.mp3', '', 1761754199, 1761754199),
(53931, 'Hosea 13:12', 'Hosea', 13, 12, 'د اسراییلو ګناهونه او بدکارۍ ثبت شوي دي او هغه لیکنې خوندي ساتل شوې دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea13_verse_12.mp3', '', 1761754199, 1761754199),
(53932, 'Hosea 13:13', 'Hosea', 13, 13, 'اسراییلو ته د ژوندي پاتې کېدلو دپاره موقع شته، خو هغوی دومره بې‌عقله دي چې ګټه ورڅخه نه اخلي، هغوی د هغه ماشوم په شان دي چې د زېږېدلو په حال کې وي او نه غواړي چې د مور د خېټې نه راووځي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea13_verse_13.mp3', '', 1761754199, 1761754199),
(53933, 'Hosea 13:14', 'Hosea', 13, 14, 'ایا زه به هغوی د قبر څخه ونه ژغورم او نه به یې د مرګ د پنجو څخه خلاصوم؟ ای مرګه، په هغوی باندې وبا راوله! ای د مړو دنیا، خپله تباهي دې راوله! زه به په دې خلکو باندې نور رحم نه کوم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea13_verse_14.mp3', '', 1761754199, 1761754199),
(53934, 'Hosea 13:15', 'Hosea', 13, 15, 'که افرایم د نورو قبیلو څخه ډېر نېکمرغه هم شي، زه به تود ختیځ باد نازل کړم او هغه به د هغوی چینې وچې او څاه‌ګانې به یې له منځه یوسي. هغه باد به د هغوی ټول قیمتي شیان له ځان سره یوسي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea13_verse_15.mp3', '', 1761754199, 1761754199),
(53935, 'Hosea 13:16', 'Hosea', 13, 16, 'سامریه باید د هغې سرکښۍ له امله چې زما په وړاندې یې کوي، سزا وزغمي. د هغې خلک به په جنګ کې مړه شي، ماشومان به په ځمکه راوغورځیږي او مړه به شي او د امیدوارو ښځو خېټې به وشکیږي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea13_verse_16.mp3', '', 1761754199, 1761754199),
(53936, 'Genesis 44:1', 'Genesis', 44, 1, 'یوسف د خپل کور ناظر ته امر وکړ: «د دې خلکو بوجۍ د غلو دانو څخه دومره ډکې کړه چې څومره دوی وړلی شي او د هر کس پیسې د هغه د بوجۍ په خوله کې کېږده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis44_verse_1.mp3', '', 1761754199, 1761754199),
(53937, 'Genesis 44:2', 'Genesis', 44, 2, 'زما د سپینو زرو جام د کشر ورور د بوجۍ په خوله کې د هغه د غلو دانو د پیسو سره کېږده.» نو څنګه چې یوسف هغه ته ویلي وو، همداسې یې وکړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis44_verse_2.mp3', '', 1761754199, 1761754199),
(53938, 'Genesis 44:3', 'Genesis', 44, 3, 'سهار وختي د یوسف ورونه د خپلو خرو سره په خپله لاره رخصت کړای شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis44_verse_3.mp3', '', 1761754199, 1761754199),
(53939, 'Genesis 44:4', 'Genesis', 44, 4, 'هغوی لا د ښار څخه دومره لېرې نه وو تللي چې یوسف د خپل کور ناظر ته وویل: «پاڅه او هغو خلکو پسې ورشه او کله چې هغوی ته ورسېدلې ورته ووایه چې تاسو ولې د نېکۍ په بدل کې بدي وکړه؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis44_verse_4.mp3', '', 1761754199, 1761754199),
(53940, 'Genesis 44:5', 'Genesis', 44, 5, 'تاسو ولې زما د بادار د سپینو زرو جام چې هغه په کې څښل کوي او فال ورباندې ګوري، غلا کړ؟ تاسو ډېر بد کار وکړ.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis44_verse_5.mp3', '', 1761754199, 1761754199),
(53941, 'Genesis 44:6', 'Genesis', 44, 6, 'کله چې ناظر هغوی ته ورورسېده، نو دا خبرې یې هغوی ته تکرار کړې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis44_verse_6.mp3', '', 1761754199, 1761754199),
(53942, 'Genesis 44:7', 'Genesis', 44, 7, 'خو هغوی ورته ځواب ورکړ: «ای زمونږ باداره، ولې داسې خبرې کوې؟ مونږ قسم خورو چې مونږ داسې کار نه دی کړی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis44_verse_7.mp3', '', 1761754199, 1761754199),
(53943, 'Genesis 44:8', 'Genesis', 44, 8, 'ګوره! هغه پیسې چې مونږ د خپلو بوجیو په خولو کې پیدا کړې بېرته مو د کنعان د خاورې څخه تاسو ته راوړلې، نو څنګه به ستا د بادار د کور څخه سره زر یا سپین زر غلا کړو؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis44_verse_8.mp3', '', 1761754199, 1761754199),
(53944, 'Genesis 44:9', 'Genesis', 44, 9, 'که هغه په مونږ کې د کوم یو سره پیدا شي، هغه دې ووژل شي او مونږ دې ستا غلامان شو.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis44_verse_9.mp3', '', 1761754199, 1761754199),
(53945, 'Genesis 44:10', 'Genesis', 44, 10, 'بیا ناظر وویل: «ډېر ښه، خو یوازې هغه چا سره چې جام پیدا شي هغه به زما غلام شي او تاسو نور به د ملامتیا څخه خلاص شئ.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis44_verse_10.mp3', '', 1761754199, 1761754199),
(53946, 'Genesis 44:11', 'Genesis', 44, 11, 'هغوی هر یو زر زر خپله بوجۍ ښکته کړه او هغه یې پرانیستلې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis44_verse_11.mp3', '', 1761754199, 1761754199),
(53947, 'Genesis 44:12', 'Genesis', 44, 12, 'بیا ناظر شروع وکړه او د مشر څخه نیولې تر کشره پورې یې په غور سره ولټول او جام د بنیامین په بوجۍ کې وموندل شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis44_verse_12.mp3', '', 1761754199, 1761754199),
(53948, 'Genesis 44:13', 'Genesis', 44, 13, 'په دې وخت کې هغوی له غمه خپل کالي وشکول، خپل خره یې بار کړل او ښار ته راستانه شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis44_verse_13.mp3', '', 1761754199, 1761754199),
(53949, 'Genesis 44:14', 'Genesis', 44, 14, 'کله چې یهودا او د هغه ورونه د یوسف کور ته راغلل، هغه لا هلته ؤ او هغوی د یوسف په مخکې پړمخې پرېوتل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis44_verse_14.mp3', '', 1761754199, 1761754199),
(53950, 'Genesis 44:15', 'Genesis', 44, 15, 'یوسف هغوی ته وویل: «تاسو څه وکړل؟ ایا تاسو نه پوهېدلئ چې زما په شان سړی کولای شي چې د فال په وسیله شیان راپیدا کړي؟»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis44_verse_15.mp3', '', 1761754199, 1761754199),
(53951, 'Genesis 44:16', 'Genesis', 44, 16, 'یهودا ځواب ورکړ: «ای باداره، تاسو ته څه ووایو؟ مونږ څه ویلی شو؟ خپله بې‌ګناهي څرنګه ثابته کړو؟ خدای زمونږ ګناه ښکاره کړه. اوس به مونږ ټول او هغه چې جام ورسره پیدا شوی دی، ستاسو غلامان شو.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis44_verse_16.mp3', '', 1761754199, 1761754199),
(53952, 'Genesis 44:17', 'Genesis', 44, 17, 'خو یوسف وویل: «نه! زه به هېڅکله داسې ونه کړم! یوازې هغه څوک به زما غلام شي چې جام ورسره موندل شوی دی او تاسو نور په خیر سره بېرته خپل پلار ته لاړ شئ.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis44_verse_17.mp3', '', 1761754199, 1761754199),
(53953, 'Genesis 44:18', 'Genesis', 44, 18, 'بیا یهودا یوسف ته ورغی او ویې ویل: «ای باداره، زه پوهېږم چې تاسو د فرعون په شان قدرت لرئ، نو په ما باندې په قهر نه شئ او د مهربانۍ له مخې اجازه راکړئ چې تاسو سره سپینې خبرې وکړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis44_verse_18.mp3', '', 1761754199, 1761754199),
(53954, 'Genesis 44:19', 'Genesis', 44, 19, 'زما باداره، تاسو زمونږ څخه پوښتنه وکړه چې ستاسو پلار یا بل ورور شته؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis44_verse_19.mp3', '', 1761754199, 1761754199),
(53955, 'Genesis 44:20', 'Genesis', 44, 20, 'مونږ ځواب درکړ چې زمونږ پلار زوړ دی او کشر ورور هم لرو چې هغه ته په سپین‌ږیرتوب کې پیدا شوی دی. د هلک ورور مړ شوی دی او هغه د خپلې مور د اولادونو څخه یوازېنی زوی دی چې ژوندی دی او پلار یې ورسره زیاته مینه کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis44_verse_20.mp3', '', 1761754199, 1761754199),
(53956, 'Genesis 44:21', 'Genesis', 44, 21, 'باداره، تاسو مونږ ته وویل چې هغه دلته راولئ چې په خپله یې ووینم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis44_verse_21.mp3', '', 1761754199, 1761754199),
(53957, 'Genesis 44:22', 'Genesis', 44, 22, 'مونږ تاسو ته وویل چې هغه هلک د خپل پلار څخه نه شي بېلېدلی او که چېرې بېل شي، نو پلار به یې مړ شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis44_verse_22.mp3', '', 1761754199, 1761754199),
(53958, 'Genesis 44:23', 'Genesis', 44, 23, 'خو تاسو مونږ ته وویل چې تر هغې پورې چې ستاسو کشر ورور تاسو سره رانه شي، نو زما مخ به بیا ونه وینئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis44_verse_23.mp3', '', 1761754199, 1761754199),
(53959, 'Genesis 44:24', 'Genesis', 44, 24, 'نو کله چې مونږ خپل پلار ته ورغلو، ستاسو خبرې مو ورته بیان کړې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis44_verse_24.mp3', '', 1761754199, 1761754199),
(53960, 'Genesis 44:25', 'Genesis', 44, 25, 'نو زمونږ پلار وویل: ‹بېرته لاړ شئ او لږې نورې غلې دانې واخلئ.›', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis44_verse_25.mp3', '', 1761754199, 1761754199),
(53961, 'Genesis 44:26', 'Genesis', 44, 26, 'خو مونږ ځواب ورکړ: ‹مونږ نه شو تللی. خو که زمونږ کشر ورور زمونږ سره وي، نو لاړ به شو. که زمونږ کشر ورور راسره نه وي، نو د هغه سړي مخ نه شو لیدلی.›', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis44_verse_26.mp3', '', 1761754199, 1761754199),
(53962, 'Genesis 44:27', 'Genesis', 44, 27, 'زمونږ پلار مونږ ته وویل: ‹تاسو پوهېږئ چې ماته زما د ښځې راحیل څخه یوازې دوه زامن پیدا شوي دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis44_verse_27.mp3', '', 1761754199, 1761754199),
(53963, 'Genesis 44:28', 'Genesis', 44, 28, 'د هغوی څخه یو یې ورک شوی دی. هغه به خامخا د کوم داړونکي ځناور له خوا ټوټې ټوټې شوی وي او له هغه وخت راهیسې مې نه دی لیدلی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis44_verse_28.mp3', '', 1761754199, 1761754199),
(53964, 'Genesis 44:29', 'Genesis', 44, 29, 'نو که تاسو دا هم زما څخه بوځئ او په هغه باندې څه وشي، نو څرنګه چې زه سپین‌ږیری یم د هغه غم له امله به چې تاسو مې ورباندې اخته کوئ مړ شم.›', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis44_verse_29.mp3', '', 1761754199, 1761754199),
(53965, 'Genesis 44:30', 'Genesis', 44, 30, 'نو اوس که چېرې زه بېرته خپل پلار ته ورشم او هلک زمونږ سره نه وي، نو که زما پلار چې ژوند یې د هلک د ژوند سره تړلی دی', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis44_verse_30.mp3', '', 1761754199, 1761754199),
(53966, 'Genesis 44:31', 'Genesis', 44, 31, 'وګوري چې هلک نشته هغه به مړ شي. هغه دومره زوړ دی چې هغه غم چې مونږ یې په هغه باندې راولو، هغه به ووژني.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis44_verse_31.mp3', '', 1761754199, 1761754199),
(53967, 'Genesis 44:32', 'Genesis', 44, 32, 'ما خپل پلار ته د دې هلک د ساتنې ضمانت ورکړی دی او ویلي مې دي: ‹که هغه مې بېرته تاته رانه‌ووست، نو زه به ټول عمر تاته ملامت یم.›', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis44_verse_32.mp3', '', 1761754199, 1761754199),
(53968, 'Genesis 44:33', 'Genesis', 44, 33, 'نو اوس ای باداره، زه به د هلک په ځای ستاسو د غلام په توګه دلته پاتې شم. هغه پرېږدئ چې د خپلو ورونو سره بېرته لاړ شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis44_verse_33.mp3', '', 1761754199, 1761754199),
(53969, 'Genesis 44:34', 'Genesis', 44, 34, 'که هلک زما سره نه وي، خپل پلار ته به څنګه بېرته ورشم؟ زه دا نه شم زغملی چې هغه بدبختي چې زما په پلار باندې به راشي، ووینم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis44_verse_34.mp3', '', 1761754199, 1761754199),
(53970, 'Job 23:1', 'Job', 23, 1, 'بيا ايُوب جواب ورکړو،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job23_verse_1.mp3', '', 1761754199, 1761754199),
(53971, 'Job 23:2', 'Job', 23, 2, '”زما شکايت په دې وخت کښې هم سخت دے، زۀ سلګۍ وهم او خُدائ پاک بيا هم ما له سزا راکوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job23_verse_2.mp3', '', 1761754199, 1761754199),
(53972, 'Job 23:3', 'Job', 23, 3, 'کاش چې ما هغه موندلے شوے، نو زۀ به د هغۀ دربار ته تلے وم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job23_verse_3.mp3', '', 1761754199, 1761754199),
(53973, 'Job 23:4', 'Job', 23, 4, 'زۀ به خپله مسئله هغۀ ته وړاندې کړم، او د هغۀ په حضور کښې به ټول عرضونه پېش کړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job23_verse_4.mp3', '', 1761754199, 1761754199),
(53974, 'Job 23:5', 'Job', 23, 5, 'چې هغه ما له څۀ جواب راکوى نو زۀ به ورته غوږ ونيسم، او چې څۀ راته وائى په هغې باندې به ځان پوهه کړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job23_verse_5.mp3', '', 1761754199, 1761754199),
(53975, 'Job 23:6', 'Job', 23, 6, 'د دومره لوئ طاقت سره به هغه زما مخالفت کوى څۀ؟ خو نه داسې نۀ ده، هغه به زما خبره په توجو سره واورى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job23_verse_6.mp3', '', 1761754199, 1761754199),
(53976, 'Job 23:7', 'Job', 23, 7, 'يو نېک سړے د هغۀ سره د خبرو کولو حق لرى، او زما قاضى خُدائ پاک به مې د تل دپاره بې‌ګناه وګرځوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job23_verse_7.mp3', '', 1761754199, 1761754199),
(53977, 'Job 23:8', 'Job', 23, 8, 'ګوره چې زۀ مخکښې ورشم نو هلته هم نۀ وى او کۀ شاته لاړ شم نو هلته هم نۀ وى،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job23_verse_8.mp3', '', 1761754199, 1761754199),
(53978, 'Job 23:9', 'Job', 23, 9, 'نۀ يې په ښى طرف موندے شم او نۀ يې په ګس طرف موندے شم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job23_verse_9.mp3', '', 1761754199, 1761754199),
(53979, 'Job 23:10', 'Job', 23, 10, 'خو هغۀ ته د هغې لارې پته ده چې کومه ما اختيار کړې ده، او کله چې هغه ما وآزمائى نو زۀ به د سرو زرو په شان صفا يم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job23_verse_10.mp3', '', 1761754199, 1761754199),
(53980, 'Job 23:11', 'Job', 23, 11, 'زۀ د هغۀ په نقشِ قدم روان وم، او زۀ هيڅکله د هغۀ د لارې نه نۀ يم اوړېدلے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job23_verse_11.mp3', '', 1761754199, 1761754199),
(53981, 'Job 23:12', 'Job', 23, 12, 'زۀ تل د هغۀ په حُکمونو عمل کوم، ما د هغۀ کلام د خپل ضرورى خوراک نه هم زيات قيمتى ګڼلے دے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job23_verse_12.mp3', '', 1761754199, 1761754199),
(53982, 'Job 23:13', 'Job', 23, 13, 'خو هغه بدلېدونکے نۀ دے، نو د هغۀ فېصله څوک بدلولے شى؟ چې د هغۀ څۀ رضا وى نو هم هغه کوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job23_verse_13.mp3', '', 1761754199, 1761754199),
(53983, 'Job 23:14', 'Job', 23, 14, 'هغه چې زما دپاره کومه منصوبه لرى نو هغه به پوره کوى، او هغه زما دپاره ډيرې منصوبې لرى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job23_verse_14.mp3', '', 1761754199, 1761754199),
(53984, 'Job 23:15', 'Job', 23, 15, 'نو په دې وجه زۀ د هغۀ په حضور کښې يرېږم، کله چې زۀ په دې سوچ کوم نو په يره کښې راګېر شم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job23_verse_15.mp3', '', 1761754199, 1761754199),
(53985, 'Job 23:16', 'Job', 23, 16, 'خُدائ پاک زۀ بې‌زړۀ کړے يم، او قادر خُدائ زۀ يرولے يم،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job23_verse_16.mp3', '', 1761754199, 1761754199),
(53986, 'Job 23:17', 'Job', 23, 17, 'خو زۀ په تيارۀ کښې راګېر يم، او تکه توره تيارۀ زما نه راتاو ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job23_verse_17.mp3', '', 1761754199, 1761754199),
(53987, 'Isaiah 46:1', 'Isaiah', 46, 1, 'دي کړوپ شوي د بابل بتان بل او نبو په حیواناتو باندې بار دي بتان د هغوی هغه بتان چې ګرځول به خلکو اوس یو دروند بار دی په ستړو حیواناتو باندې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah46_verse_1.mp3', '', 1761754199, 1761754199),
(53988, 'Isaiah 46:2', 'Isaiah', 46, 2, 'دي کړوپ شوي دواړه خدایان ژغورلی نه شي هغوی خپل ځانونه او اسیران شوي دي دوی په خپله', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah46_verse_2.mp3', '', 1761754199, 1761754199),
(53989, 'Isaiah 46:3', 'Isaiah', 46, 3, '«ای د یعقوب اولادې ای زما د قوم اسراییلو نه پاتې شویو خلکو ماته غوږ ونیسئ ما کړی پام په تاسو له زېږېدو نه مخکې ستاسو ساتنه مې کوله د مور له خېټې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah46_verse_3.mp3', '', 1761754199, 1761754199),
(53990, 'Isaiah 46:4', 'Isaiah', 46, 4, 'زه ستاسو خدای یم تر زوړوالي پورې او کوم به پام په تاسو تر سپین ږیرتوب پورې ما پیدا کړي یئ او ستاسو ملاتړ به وکړم پام به وکړمه په تاسو او تاسو به وژغورمه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah46_verse_4.mp3', '', 1761754199, 1761754199),
(53991, 'Isaiah 46:5', 'Isaiah', 46, 5, 'برابروئ او پرتله کوئ مې تاسو چا سره؟ ایا زه لرمه ورته والی له کوم چا سره؟ ایا بل څوک شته زما په شان؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah46_verse_5.mp3', '', 1761754199, 1761754199),
(53992, 'Isaiah 46:6', 'Isaiah', 46, 6, 'خلک خلاصوي خپلې کڅوړې او سره زر ترې غورځوي هغوی سپین زر تلي په تله باندې ورکوي هغوی زرګر ته پیسې چې ورته بت جوړ کړي بیا ورته کړي سجده او عبادت یې کوي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah46_verse_6.mp3', '', 1761754199, 1761754199),
(53993, 'Isaiah 46:7', 'Isaiah', 46, 7, 'اوچتوي هغوی دا بت خپلو اوږو ته او وړي هغه بیا یې کېږدي په خپل ځای او ولاړ وي هلته له خپله ځایه خوځېدلی نه شي که څوک وکړي فریاد ورته ورته نه شي ورکولی ځواب او له مصیبته یې ژغورلی نه شي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah46_verse_7.mp3', '', 1761754199, 1761754199),
(53994, 'Isaiah 46:8', 'Isaiah', 46, 8, 'ای ګناهکارو خلکو، دا په یاد ساتئ ما چې څه کړي دي، مه هېروئ هغه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah46_verse_8.mp3', '', 1761754199, 1761754199),
(53995, 'Isaiah 46:9', 'Isaiah', 46, 9, 'څه چې پېښ شوي وو ډېر پخوا هغه په یاد راوړئ ځکه چې زه یوازېنی خدای یم زه یم خدای او بل خدای نشته زما په شان', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah46_verse_9.mp3', '', 1761754199, 1761754199),
(53996, 'Isaiah 46:10', 'Isaiah', 46, 10, 'ما د شروع نه دا ویلي وو چې څه به کیږي د ډېر پخوا نه مې ویلي وو چې څه به پېښ شي ما وویل چې بریالي کیږي به زما ټولې نقشې اراده چې د هر کار وکړمه زه هغه سرته رسوم', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah46_verse_10.mp3', '', 1761754199, 1761754199),
(53997, 'Isaiah 46:11', 'Isaiah', 46, 11, 'زه غواړمه یو کس چې له ختیځه راشي له لېرې هېواده چې عملي کړي نقشه زما هغه به ووهي غوټه لکه د باز په شان څه چې وویل ما هغه به وکړم دا اراده ده زما او زه به یې سرته رسومه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah46_verse_11.mp3', '', 1761754199, 1761754199),
(53998, 'Isaiah 46:12', 'Isaiah', 46, 12, 'ای سرزورو خلکو، ماته غوږ ونیسئ تاسو فکر کوئ چې ډېر لېرې دی بری', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah46_verse_12.mp3', '', 1761754199, 1761754199),
(53999, 'Isaiah 46:13', 'Isaiah', 46, 13, 'رانژدې کومه ورځ د بري او نه ده لېرې هغه زه به درکړمه خلاصون تاسو ته بې له ځنډه زه به وژغورم صهیون او اسراییلو ته به ورکړم خپل جلال»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah46_verse_13.mp3', '', 1761754199, 1761754199),
(54000, 'Job 14:1', 'Job', 14, 1, 'يو فانى انسان، د مور د خېټې نه پېدا، د يو څو ورځو مېلمه او د تکليفونو نه ډک،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job14_verse_1.mp3', '', 1761754199, 1761754199),
(54001, 'Job 14:2', 'Job', 14, 2, 'د يو ګل په شان راوټوکيږى او مړاوے شى، هغه د سورى په شان منډه وهى زر زر ختميږى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job14_verse_2.mp3', '', 1761754199, 1761754199),
(54002, 'Job 14:3', 'Job', 14, 3, 'تۀ په يو کمزورى مخلوق باندې نظر ساتې؟ او تۀ ما سره عدالت کوې؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job14_verse_3.mp3', '', 1761754199, 1761754199),
(54003, 'Job 14:4', 'Job', 14, 4, 'د يو ناپاک څيز نه څوک پاک څيز راويستلے شى؟ دا کار هيڅ څوک هم نۀ شى کولے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job14_verse_4.mp3', '', 1761754199, 1761754199),
(54004, 'Job 14:5', 'Job', 14, 5, 'ځکه چې د هغوئ د عُمر حد مقرر دے، او د هغوئ د مياشتو شمېر تا ته معلوم دے، او دا تا مقررې کړې دى او دا نۀ شى بدلېدلے،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job14_verse_5.mp3', '', 1761754199, 1761754199),
(54005, 'Job 14:6', 'Job', 14, 6, 'نو مونږ پرېږده چې آرام وکړُو. مونږ د مزدورانو په شان يُو او مونږ پرېږده چې خپل کار په خېر ختم کړُو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job14_verse_6.mp3', '', 1761754199, 1761754199),
(54006, 'Job 14:7', 'Job', 14, 7, 'کۀ يوه ونه هم راوغورزولے شى، نو امکان شته دا به بيا راوشى، او د دې شنۀ کېدل به نۀ ختميږى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job14_verse_7.mp3', '', 1761754199, 1761754199),
(54007, 'Job 14:8', 'Job', 14, 8, 'اګر چې د دې جرړې په زمکه کښې زړيږى، او د دې مونډ په زمکه کښې ورَستيږى،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job14_verse_8.mp3', '', 1761754199, 1761754199),
(54008, 'Job 14:9', 'Job', 14, 9, 'خو يو څاڅکى اوبو سره به دا بيا را شنه شى، او د يوې نوې ونې په شان به دا بيا څانګې ونيسى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job14_verse_9.mp3', '', 1761754199, 1761754199),
(54009, 'Job 14:10', 'Job', 14, 10, 'خو چې انسان مړ شى نو طاقت يې ختم شى، چې انسان ساه ورکړى نو بيا چرته وى؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job14_verse_10.mp3', '', 1761754199, 1761754199),
(54010, 'Job 14:11', 'Job', 14, 11, 'لکه څنګه چې د يو ډنډ اوبۀ کميږى، او په سيند کښې اوبۀ اوچيږى،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job14_verse_11.mp3', '', 1761754199, 1761754199);